for name,cat,eq,cue,spec in E:
    t={}
    for item in spec.split(','):
        k,l=item.rsplit(':',1); l=int(l)
        ks=G.get(k,[k])
        for kk in ks:
            key,_,part=kk.partition('|')
            assert key in DB,(name,key)
            if part: assert part in parts.get(key,set()),(name,key,part,parts.get(key))
            t[(key,part)]=max(t.get((key,part),0),l)
    out.append({'n':name,'c':cat,'e':eq,'q':cue,'t':[[k,p,l] for (k,p),l in sorted(t.items(),key=lambda x:-x[1])]})
