def expand(spec):
    res=[]
    if not spec: return res
    for item in spec.split(','):
        k,l=item.rsplit(':',1); l=int(l)
        for kk in G.get(k,[k]):
            key,_,part=kk.partition('|'); assert key in DB,key
            if part: assert part in parts.get(key,set()),(key,part)
            res.append([key,part,l])
    return res
for n,groups in VARS.items():
    assert n in idx,n
    idx[n]['v']=[[g,[[o,expand(s)] for o,s in opts]] for g,opts in groups]
